UPDATE account_group
SET name = #{name}, remark = #{remark}, updated_at = #{updatedAt}
WHERE id = #{id} AND deleted_at IS NULL

UPDATE account_group SET deleted_at = #{deletedAt}
WHERE deleted_at IS NULL
