#{id}

UPDATE account_group
SET marketing_occupancy_type = NULL,
    marketing_occupancy_task_id = NULL,
    marketing_locked_at = NULL,
    updated_at = #{now}
WHERE id = #{groupId}
  AND marketing_occupancy_type = #{occupancyType}
  AND marketing_occupancy_task_id = #{taskId}
